func (this *Table) gtk3_key_press_event_(widget int64, event int64) int64 {
	var key []int32 = make([]int32, 1)
	gtk.GDKGdk_event_get_keyval(event, key)
	switch key[0] {
	case gtk.GDKGDK_Return:
		var keymask int32 = this.Gdk3_event_get_state(event)
		if (keymask & (gtk.GDKGDK_SUPER_MASK | gtk.GDKGDK_META_MASK | gtk.GDKGDK_HYPER_MASK | gtk.GDKGDK_MOD1_MASK)) == 0 {
			this.SendTreeDefaultSelection()
		}
		break
	case gtk.GDKGDK_space:
		if (this.style & CHECK) != 0 {
			var selected []*TableItem = this.GetSelection()
			for i := int32(0); i < int32(len(selected)); i++ {
				this.ToggleItemAndSendEvent(selected[i])
			}
			return int64(1)
		}
		break
	}
	return this.Composite.gtk3_key_press_event_(widget, event)
}

