func (this *Table) gtk3_button_release_event_(widget int64, event int64) int64 {
	var eventX []float64 = make([]float64, 1)
	var eventY []float64 = make([]float64, 1)
	gtk.GDKGdk_event_get_coords(event, eventX, eventY)
	var eventButton []int32 = make([]int32, 1)
	var eventState []int32 = make([]int32, 1)
	gtk.GDKGdk_event_get_button(event, eventButton)
	gtk.GDKGdk_event_get_state(event, eventState)
	var eventRX []float64 = make([]float64, 1)
	var eventRY []float64 = make([]float64, 1)
	gtk.GDKGdk_event_get_root_coords(event, eventRX, eventRY)
	var eventGdkResource int64 = gtk.GDKGdk_event_get_window(event)
	if eventGdkResource != gtk.GTK3Gtk_tree_view_get_bin_window(this.Handle) {
		return int64(0)
	}
	this.lastInput.X = int32(eventX[0])
	this.lastInput.Y = int32(eventY[0])
	if this.ContainedInRegion(this.lastInput.X, this.lastInput.Y) {
		return int64(0)
	}
	if (this.state&WidgetDRAG_DETECT) != 0 && this.Hooks(DragDetect) && gtk.OSIsWayland() {
		var path []int64 = make([]int64, 1)
		var selection int64 = gtk.GTKGtk_tree_view_get_selection(this.Handle)
		gtk.GTKGtk_tree_selection_set_select_function(selection, int64(0), int64(0), int64(0))
		if gtk.GTKGtk_tree_view_get_path_at_pos(this.Handle, int32(eventX[0]), int32(eventY[0]), path, nil, nil, nil) && path[0] != 0 && gtk.GTKGtk_tree_selection_path_is_selected(selection, path[0]) {
			this.selectionCountOnRelease = this.GetSelectionCount()
			if (eventState[0] & (gtk.GDKGDK_CONTROL_MASK | gtk.GDKGDK_SHIFT_MASK)) == 0 {
				gtk.GTKGtk_tree_view_set_cursor(this.Handle, path[0], int64(0), false)
			}
			if (eventState[0]&gtk.GDKGDK_CONTROL_MASK) != 0 && this.selectionCountOnRelease == this.selectionCountOnPress {
				gtk.GTKGtk_tree_selection_unselect_path(selection, path[0])
			}
		}
	}
	return this.Composite.gtk3_button_release_event_(widget, event)
}

